export type RefundTenderAllocation = { /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "amount_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "destination"?: "original" | "replacement" | (string & {}); "destination_cards"?: Array<RefundGiftCardDestination>; /** Flint-normalized refund failure reason. Unknown provider values are returned as refund_failed. */ "failure_reason"?: "expired_or_canceled_card" | "lost_or_stolen_card" | "insufficient_funds" | "insufficient_available_balance" | "declined" | "merchant_request" | "payment_disputed" | "payment_refund_failed" | "payment_refund_not_attempted" | "refund_failed" | (string & {}); "gift_card_id"?: string; "gift_card_redemption_id"?: string; "payment_intent_id"?: string; "refund_allocation_id": string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "refunded_tip_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "status": "pending" | "requires_action" | "in_transit" | "succeeded" | "failed" | "canceled" | "partially_succeeded" | (string & {}); "tender_type": "payment_intent" | "gift_card_redemption" | (string & {}); };
